/* libselinux for the arm64 native runtime (PLAN P7.1, step 0.1). Android's servicemanager and friends insist on SELinux
 * contexts and access checks; a desktop has no Android policy. This answers "allowed" with one fixed context: the access
 * decisions Android makes with SELinux do not exist here, the host's own isolation (P6) is the boundary. Everything else the
 * real library exports is a weak do-nothing stub generated by scripts/build-native-arm64.sh. Mapped by cfg.d (libselinux.so). */
#include <stdlib.h>
#include <string.h>

#define CONTEXT "u:r:apklayer:s0"

int getcon(char **con) { *con = strdup(CONTEXT); return 0; }
int getpidcon(int pid, char **con) { (void)pid; return getcon(con); }
int getpeercon(int fd, char **con) { (void)fd; return getcon(con); }
void freecon(char *con) { free(con); }

int selinux_status_open(int fallback) { (void)fallback; return 0; }
void selinux_status_close(void) {}
int selinux_status_updated(void) { return 0; }
int selinux_check_access(const char *s, const char *t, const char *cls, const char *perm, void *audit)
{ (void)s; (void)t; (void)cls; (void)perm; (void)audit; return 0; }
void selinux_set_callback(int type, void *callback) { (void)type; (void)callback; }
int selinux_log_callback(int type, const char *fmt, ...) { (void)type; (void)fmt; return 0; }
int selinux_vendor_log_callback(int type, const char *fmt, ...) { (void)type; (void)fmt; return 0; }

static int handle; /* any non-null pointer is a label handle */
void *selinux_android_service_context_handle(void) { return &handle; }
void *selinux_android_vendor_service_context_handle(void) { return &handle; }
int selabel_lookup(void *h, char **con, const char *key, int type)
{ (void)h; (void)key; (void)type; *con = strdup("u:object_r:default_android_service:s0"); return 0; }
void selabel_close(void *h) { (void)h; }
